import math

primes_to_check = [2, 3, 5, 7, 11, 13, 17]
results = {}

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

for q in primes_to_check:
    # Calculate N = q^2 - q + 1
    N = q*q - q + 1

    # Check if N is a perfect cube
    # Estimate the cube root
    k_float = N**(1/3)
    k_int = round(k_float)

    # Check if k_int cubed equals N
    if k_int**3 == N:
        # N is a perfect cube, k = k_int
        k = k_int

        # Check if k is prime and k != q
        if is_prime(k) and k != q:
            results[q] = f"Solution found: k={k}, N={N} = {k}^3. k is prime and k != q."
        else:
            results[q] = f"Not a solution: N={N} = {k}^3, but k={k} is either not prime or k=q."
    else:
        results[q] = f"Not a cube: N={N}."

print(results)
